snippet_css:
:root{
  --bg: #E0E5EC;
  --fg: #2D3748;
  --muted: #535E70;
  --surface: #F1F4F9;
  --border: #C8D0DC;
  --accent: #4F46D6;
  --accent-fg: #FFFFFF;
  --radius: 22px;
  --radius-sm: 14px;
  --shadow: 9px 9px 18px #A3B1C6,-9px -9px 18px #FFFFFF;
  --btn-shadow: 6px 6px 12px #A3B1C6,-6px -6px 12px #FFFFFF;
  --art-bg: radial-gradient(circle at 30% 28%,#FFFFFF,transparent 46%),linear-gradient(160deg,#E8EDF4,#D3DAE6);
  --media-bg: radial-gradient(circle at 34% 30%,#FFFFFF,transparent 48%),linear-gradient(160deg,#E4E9F1,#D3DAE6);
  --cta-bg: #EDF1F7;
  --input-bg: #E8ECF3;
  --ok: #1F7A57;
  --warn: #A32A3C;
  --font-display: Poppins,'Noto Sans TC',sans-serif;
  --font-body: Poppins,'Noto Sans TC',sans-serif;
  --font-mono: 'Roboto Mono',ui-monospace,Menlo,monospace;
  --focus-ring: var(--accent);
}

